/**
 * Options for starting observations (spans).
 *
 * @public
 */
export type StartObservationOptions = {
  /** Custom start time for the observation */
  startTime?: Date;
  /** Parent span context to attach this observation to */
  parentSpanContext?: SpanContext;
  /** Optional links to external or related spans */
  links?: Link[];
};

/**
 * Options for startObservation function.
 *
 * @public
 */
export type StartObservationOpts = StartObservationOptions & {
  /** Type of observation to create. Defaults to 'chain' */
  asType?: ObservationType;
};

/**
 * Creates an OpenTelemetry span with the tracer.
 *
 * @param params - Parameters for span creation
 * @returns The created OpenTelemetry span
 * @internal
 */
function createOtelSpan(params: {
  name: string;
  startTime?: TimeInput;
  parentSpanContext?: SpanContext;
  links?: Link[];
}): Span {
  return getTracer().startSpan(
    params.name,
    {
      startTime: params.startTime,
      links: params.links || [],
    },
    createParentContext(params.parentSpanContext),
  );
}

/**
 * Creates a parent context from a span context.
 *
 * @param parentSpanContext - The span context to use as parent
 * @returns The created context or undefined if no parent provided
 * @internal
 */
function createParentContext(
  parentSpanContext?: SpanContext,
): ReturnType<typeof trace.setSpanContext> | undefined {
  if (!parentSpanContext) return;
  return trace.setSpanContext(context.active(), parentSpanContext);
}

/**
 * Creates a NonRecordingSpan that safely accepts all Span operations as no-ops.
 * Used as a fallback when observation creation fails, ensuring observability
 * never blocks business logic.
 *
 * @internal
 */
function createNoopSpan(): Span {
  return trace.wrapSpanContext(INVALID_SPAN_CONTEXT);
}

/**
 * Creates a no-op observation of the specified type.
 * All methods (update, end, setErrorStatus, etc.) are safe to call but do nothing.
 *
 * @param asType - The observation type to create
 * @returns A no-op observation instance
 * @internal
 */
function createNoopObservation(asType: ObservationType = "chain"): Observation {
  const otelSpan = createNoopSpan();
  switch (asType) {
    case "llm":
      return new ObservationLLM({ otelSpan });
    case "embedding":
      return new ObservationEmbedding({ otelSpan });
    case "agent":
      return new ObservationAgent({ otelSpan });
    case "tool":
      return new ObservationTool({ otelSpan });
    case "retriever":
      return new ObservationRetriever({ otelSpan });
    case "reranker":
      return new ObservationReranker({ otelSpan });
    case "evaluator":
      return new ObservationEvaluator({ otelSpan });
    case "guardrail":
      return new ObservationGuardrail({ otelSpan });
    case "chain":
    default:
      return new ObservationChain({ otelSpan });
  }
}

